// YaHacks v3 — native editable Figma screens.
const BOARD = '';
const T = {
 bg:'#181A1B',card:'#252827',line:'#383C38',
 white:'#F2F3EE',muted:'#B2B6B0',
 yellow:'#F4D35E',sage:'#BEC8B2',ink:'#181A1B'
};
const FONT = {
 body:{family:'Onest',style:'Regular'},
 medium:{family:'Onest',style:'Medium'},
 display:{family:'Unbounded',style:'Medium'}
};
const made = [];
let imageHash;

function track(n){made.push(n);return n;}
function rgb(h){
 return {
  r:parseInt(h.slice(1,3),16)/255,
  g:parseInt(h.slice(3,5),16)/255,
  b:parseInt(h.slice(5,7),16)/255
 };
}
function fill(h){return [{type:'SOLID',color:rgb(h)}];}
function place(p,n,x,y){
 p.appendChild(n);n.x=x;n.y=y;return n;
}
function frame(p,name,x,y,w,h,c=null,r=0){
 const n=track(figma.createFrame());
 n.name=name;n.resize(w,h);
 n.fills=c?fill(c):[];
 n.cornerRadius=r;n.clipsContent=true;
 return place(p,n,x,y);
}
function rect(p,name,x,y,w,h,c,r=0){
 const n=track(figma.createRectangle());
 n.name=name;n.resize(w,h);
 n.fills=fill(c);n.cornerRadius=r;
 return place(p,n,x,y);
}
function txt(p,s,x,y,size=14,c=T.white,font='body',w=null){
 const n=track(figma.createText());
 n.name=s;n.fontName=FONT[font];n.fontSize=size;
 n.lineHeight={unit:'PIXELS',value:Math.round(size*1.4)};
 n.fills=fill(c);n.characters=s;
 n.textAutoResize='WIDTH_AND_HEIGHT';
 if(w!==null){
  n.resize(w,n.height);n.textAutoResize='HEIGHT';
 }
 return place(p,n,x,y);
}

