function poster(p,x,y,w,h,label='STUDENT\nDATA CUP'){
 const n=frame(p,'Event poster / editable vectors',
  x,y,w,h,T.sage,0);
 txt(n,label,16,15,24,T.ink,'medium',w-113);
 const s=18;
 for(let row=0;row<4;row++){
  for(let col=0;col<3;col++){
   if((row+col)%2===0){
    rect(n,'Poster checker',w-100+col*s,18+row*s,s,s,T.ink);
   }
  }
 }
 const d=track(figma.createEllipse());
 d.name='Poster circle';d.resize(25,25);d.fills=fill(T.ink);
 place(n,d,w-33,18);
 return n;
}
function eventCard(p,y,title,date,where,art){
 const n=frame(p,'Event / '+title,20,y,350,197,T.card,12);
 if(art==='poster'){
  poster(n,0,0,350,125);
 }else{
  photo(n,'Event cover',0,0,350,125,CROP.workshop);
 }
 txt(n,title,14,135,18,T.white,'medium',300);
 icon(n,'bookmark',316,137,20);
 metadata(n,171,date,where,14);
 return n;
}
function eventRow(p,y,title,date,where,posterArt=false){
 const n=frame(p,'Event / '+title,20,y,350,70,T.card,9);
 if(posterArt){
  rect(n,'Poster thumbnail',0,0,86,70,T.yellow);
  txt(n,'PRODUCT\nHACK',7,10,14,T.ink,'medium',78);
 }else{
  photo(n,'Event thumbnail',0,0,86,70,CROP.event);
 }
 txt(n,title,98,10,14,T.white,'medium',224);
 icon(n,'calendar',98,41,14);
 txt(n,date,118,40,11,T.muted,'body',80);
 icon(n,where==='Онлайн'?'wifi':'pin',204,41,14);
 txt(n,where==='Санкт-Петербург'?'СПб':where,
  223,40,11,T.muted,'body',90);
 icon(n,'bookmark',324,12,16);
 return n;
}
