function decode64(s){
 const abc='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
 const out=new Uint8Array(Math.floor(s.length*3/4));
 let count=0,bits=0,value=0;
 for(let i=0;i<s.length;i++){
  const n=abc.indexOf(s[i]);
  if(n<0)continue;
  value=(value<<6)|n;bits+=6;
  if(bits>=8){
   bits-=8;out[count++]=(value>>bits)&255;
  }
 }
 return out.slice(0,count);
}
async function main(){
 try{
  await Promise.all(Object.values(FONT).map(f=>figma.loadFontAsync(f)));
 }catch(e){
  throw new Error(
   'Установите Onest Regular/Medium и Unbounded Medium, затем перезапустите Figma. '+e.message
  );
 }
 imageHash=figma.createImage(decode64(BOARD)).hash;
 const origin=figma.currentPage.children.reduce(
  (x,n)=>Math.max(x,n.x+n.width+80),0
 );
 const names=[
  '01 / Главная','02 / События','03 / Люди',
  '04 / Профиль участника','05 / Мой профиль'
 ];
 const screens=names.map((n,i)=>screen(n,i,origin));
 [home,events,people,profile,own].forEach(
  (build,i)=>build(screens[i])
 );
 figma.currentPage.selection=screens;
 figma.viewport.scrollAndZoomIntoView(screens);
 figma.closePlugin('YaHacks v3: 5 редактируемых экранов созданы.');
}
const runPromise=main().catch(error=>{
 for(let i=made.length-1;i>=0;i--){
  if(!made[i].removed)made[i].remove();
 }
 figma.closePlugin('Ошибка: '+error.message);
});